for f in glob.glob('airlines/*.csv'):
 d=pd.read_csv(f); car=f.split('/')[-1][:2]
 if car=='AS':
  off=d.origin.map(aps.set_index('airport').utc_offset_hours)
  d['_local_sched']=pd.to_datetime(d.date_utc+' '+d.sched_dep_utc,utc=True)+pd.to_timedelta(off,unit='h')
  print('AS local date counts',d._local_sched.dt.date.min(),d._local_sched.dt.date.max(), 'outside JanFeb',((d._local_sched<'2025-01-01')|(d._local_sched>='2025-03-01')).sum())
  print(d.loc[(d._local_sched<'2025-01-01')|(d._local_sched>='2025-03-01'),['flight_id','date_utc','origin','sched_dep_utc','_local_sched']])
 if car=='B6':
  z=d[d.flight_id.duplicated(False)].sort_values('flight_id'); print('B6 dup rows'); print(z.to_string(index=False))

# inspect raw clock differences that are very negative; these require rollover according to documentation if after-midnight
for f in glob.glob('airlines/*.csv'):
 d=pd.read_csv(f); car=f.split('/')[-1][:2]
 if car!='AS':
  s=pd.to_datetime(d.sched_dep,format='%H:%M'); a=pd.to_datetime(d.actual_dep,format='%H:%M',errors='coerce')
  raw=(a-s).dt.total_seconds()/60
  q=d.loc[(~d.cancelled)&(raw<-120),['flight_id','date','sched_dep','actual_dep','cancelled']].copy(); q['raw']=raw[q.index]
  if len(q): print(car,q.to_string(index=False))

